export const SPRUCE_FENCE = "spruce_fence";
export const SPRUCE_STAIRS = "spruce_stairs";
export const SPRUCE_SLAB = "spruce_slab";
export const SPRUCE_PRESSURE_PLATE = "spruce_pressure_plate";
